/* Learning views share the scored state with practice; all answers remain on this device. */
(function(root){'use strict';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function create({engine,links,bank,chapters,onProgress,onReset}){
 const $=id=>document.getElementById(id),html=escape,byId=new Map(bank.map(q=>[q.id,q]));
 let step=0,current=null,resultId=null,confirmSubmit=false;
 const number=n=>Number(n).toLocaleString('en-GB',{maximumSignificantDigits:8,notation:Math.abs(n)>0&&(Math.abs(n)<.0001||Math.abs(n)>=1e7)?'scientific':'standard'});
 const resources=q=>'<nav class="learning-resources" aria-label="Resources for this exercise">'+links.resources(q).map(r=>'<a href="'+html(r.href)+'"><small>'+html(r.kind)+'</small>'+html(r.label)+' →</a>').join('')+'</nav>';
 function storage(){const text=engine.storageState==='saved'?'Progress and answers are saved in this browser on this device.':engine.storageState==='incompatible'?'Saved learning data uses a newer format. This session works without replacing it.':'Browser storage is unavailable. Progress and answers will last only for this session.';document.querySelectorAll('.learning-storage').forEach(n=>n.textContent=text);}
 function progress(){const rows=engine.summary(),done=engine.completed.length,resume=engine.resume();
  $('learning-progress').innerHTML='<div class="learning-overview"><div><h3>Your progress</h3><p><strong>'+done+' / '+bank.length+'</strong> exercises answered correctly at least once.</p><progress aria-label="Overall exercise completion" value="'+done+'" max="'+bank.length+'"></progress></div>'+(resume?'<a class="main-btn" href="#exercise/'+encodeURIComponent(resume)+'">'+(done===bank.length?'Review exercises':'Continue learning')+' →</a>':'')+'</div><p class="learning-storage helper"></p><div class="learning-chapters">'+rows.map(c=>'<article class="learning-chapter"><h4>'+c.number+' · '+html(c.title)+'</h4><p>'+c.completed+' / '+c.total+' completed</p><progress aria-label="Chapter '+c.number+' completion" value="'+c.completed+'" max="'+c.total+'"></progress><ul>'+c.levels.map(l=>'<li><span>'+html(l.level)+'</span><span>'+l.completed+' / '+l.total+'</span></li>').join('')+'</ul><a href="#exercise/'+encodeURIComponent(c.resume)+'">'+(c.completed===c.total?'Review chapter':'Continue chapter')+' →</a></article>').join('')+'</div><button type="button" id="learning-reset" class="quiet-button subtle">Reset learning progress</button>';
  $('learning-reset').onclick=reset;storage();
 }
 function reset(){if(!window.confirm('Reset exercise progress, saved answers and self-test history on this device?'))return;engine.reset();onProgress();onReset?.();progress();selftest();}
 function practice(q){current=q;step=0;const p=engine.draft(q.id);engine.open(q.id);$('exercise-answer').value=p.raw;$('exercise-answer').setAttribute('aria-describedby','exercise-unit answer-format exercise-feedback');$('exercise-answer').removeAttribute('aria-invalid');$('exercise-question').tabIndex=-1;
  $('exercise-resources').innerHTML=resources(q);$('exercise-step-list').innerHTML='';$('exercise-steps').hidden=true;$('next-solution-step').disabled=!p.attempts;$('next-solution-step').textContent='Reveal next solution step';$('show-solution').disabled=!p.attempts;storage();return p.attempts>0;
 }
 function checked(result){$('exercise-answer').setAttribute('aria-invalid',String(!result.correct));if(result.valid)$('next-solution-step').disabled=false;storage();}
 $('next-solution-step').addEventListener('click',()=>{if(!current||!engine.draft(current.id).attempts)return;step=Math.min(current.steps.length,step+1);$('exercise-step-list').innerHTML=current.steps.slice(0,step).map(s=>'<li>'+html(s)+'</li>').join('');$('exercise-steps').hidden=false;$('next-solution-step').disabled=step===current.steps.length;$('next-solution-step').textContent=step===current.steps.length?'All steps revealed':'Reveal step '+(step+1);});
 $('exercise-answer').addEventListener('input',()=>{if(!current||$('exercise-answer').disabled)return;engine.setAnswer(current.id,$('exercise-answer').value);$('exercise-answer').removeAttribute('aria-invalid');$('exercise-feedback').textContent='';});
 function historyMarkup(){const list=engine.history;return '<section class="test-history"><h4>Recent self-tests</h4>'+(list.length?'<ul>'+list.map(t=>'<li><a href="#selftest/'+encodeURIComponent(t.id)+'">'+html(new Date(t.submittedAt).toLocaleString('en-GB'))+' · '+t.score+' / '+t.items.length+'</a></li>').join('')+'</ul>':'<p>No submitted self-tests yet.</p>')+'<p class="helper">The last 10 submitted tests are stored on this device.</p></section>';}
 function setup(){const pane=$('learning-selftest');pane.innerHTML='<h3>Build a self-test</h3><p>Choose chapters and difficulty. Hints and solutions become available after you submit. You can leave and resume an unfinished test.</p><form id="test-setup"><fieldset class="test-chapters"><legend>Chapters</legend><div class="learning-actions"><button type="button" id="test-all">Select all</button><button type="button" id="test-none">Clear selection</button></div><div class="test-chapter-grid">'+chapters.map(c=>'<label><input type="checkbox" name="test-chapter" value="'+c.number+'" checked><span>'+c.number+' · '+html(c.title)+'</span></label>').join('')+'</div></fieldset><div class="test-settings"><label>Difficulty<select id="test-level"><option value="All">All levels</option>'+engine.levels.map(l=>'<option>'+l+'</option>').join('')+'</select></label><label>Number of questions<input id="test-count" type="number" min="1" max="50" value="10" required aria-describedby="test-pool"></label></div><p id="test-pool" class="helper" aria-live="polite"></p><p id="test-error" role="alert"></p><button class="main-btn" type="submit">Start self-test</button></form>'+historyMarkup();
  const selected=()=>[...pane.querySelectorAll('[name="test-chapter"]:checked')].map(n=>Number(n.value));
  const update=()=>{const count=engine.pool(selected(),$('test-level').value).length,max=Math.min(50,count);$('test-count').max=String(max||1);$('test-pool').textContent=count?count+' questions available. Choose 1–'+max+'.':'Select at least one chapter.';if(Number($('test-count').value)>max&&max)$('test-count').value=String(max);};
  $('test-setup').addEventListener('change',update);for(const [id,checked]of [['test-all',true],['test-none',false]])$(id).onclick=()=>{pane.querySelectorAll('[name="test-chapter"]').forEach(n=>n.checked=checked);update();};
  $('test-setup').onsubmit=event=>{event.preventDefault();try{const t=engine.startTest({chapters:selected(),level:$('test-level').value,count:Number($('test-count').value)});resultId=null;confirmSubmit=false;location.hash='selftest/'+t.id;selftest(t.id);focusTest();}catch(e){$('test-error').textContent=e.message;}};update();
 }
 function focusTest(){const heading=$('test-question')||$('test-result-title');heading?.focus();}
 function active(t){const q=t.items[t.index],answered=t.items.filter(q=>String(t.answers[q.id]??'').trim()).length,pane=$('learning-selftest');
  pane.innerHTML='<div class="section-line"><h3>Self-test in progress</h3><span>'+answered+' / '+t.items.length+' answered</span></div><p class="helper">Answers are checked when you submit. Leaving this page keeps your unfinished test.</p><nav class="test-question-nav" aria-label="Self-test questions">'+t.items.map((q,i)=>'<button type="button" data-question="'+i+'" '+(i===t.index?'aria-current="step" ':'')+'aria-label="Question '+(i+1)+(String(t.answers[q.id]??'').trim()?', answered':', unanswered')+'">'+(i+1)+(String(t.answers[q.id]??'').trim()?' •':'')+'</button>').join('')+'</nav><div class="exercise-card"><p>Question '+(t.index+1)+' / '+t.items.length+' · Chapter '+q.chapter+' · '+html(q.level)+'</p><h4 id="test-question" tabindex="-1">'+html(q.prompt)+'</h4><label for="test-answer">Your answer <span id="test-unit">'+html(q.unit)+'</span></label><input id="test-answer" class="test-answer" type="text" inputmode="decimal" autocomplete="off" maxlength="100" value="'+html(t.answers[q.id]??'')+'" aria-describedby="test-unit test-answer-format"><p id="test-answer-format" class="helper">Use a decimal point or comma; scientific notation is accepted. Match the displayed unit.</p><div class="learning-actions"><button type="button" id="test-prev" '+(t.index===0?'disabled':'')+'>Previous question</button><button type="button" id="test-next" '+(t.index===t.items.length-1?'disabled':'')+'>Next question</button></div></div><div class="learning-actions"><button type="button" id="test-review" class="main-btn">Review and submit</button><button type="button" id="test-discard" class="quiet-button">Discard unfinished test</button></div><div id="test-submit-confirm" '+(confirmSubmit?'':'hidden')+'><h4 tabindex="-1" id="test-submit-title">Submit this self-test?</h4><p id="test-submit-summary"></p><div class="learning-actions"><button type="button" id="test-submit" class="main-btn">Submit answers</button><button type="button" id="test-continue">Keep working</button></div></div>';
  const refreshSummary=()=>{const a=engine.activeTest,n=a.items.filter(q=>String(a.answers[q.id]??'').trim()).length;$('test-submit-summary').textContent=n+' answered; '+(a.items.length-n)+' unanswered. Unanswered and invalid answers count as incorrect.';};refreshSummary();
  $('test-answer').oninput=()=>{engine.answerTest(q.id,$('test-answer').value);const a=engine.activeTest,n=a.items.filter(q=>String(a.answers[q.id]??'').trim()).length;pane.querySelector('.section-line span').textContent=n+' / '+a.items.length+' answered';const b=pane.querySelector('[data-question="'+a.index+'"]'),has=!!$('test-answer').value.trim();b.textContent=(a.index+1)+(has?' •':'');b.setAttribute('aria-label','Question '+(a.index+1)+(has?', answered':', unanswered'));refreshSummary();storage();};
  const move=i=>{engine.moveTest(i);confirmSubmit=false;selftest(t.id);focusTest();};pane.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>move(Number(b.dataset.question)));$('test-prev').onclick=()=>move(t.index-1);$('test-next').onclick=()=>move(t.index+1);
  $('test-review').onclick=()=>{confirmSubmit=true;$('test-submit-confirm').hidden=false;refreshSummary();$('test-submit-title').focus();};$('test-continue').onclick=()=>{confirmSubmit=false;$('test-submit-confirm').hidden=true;$('test-answer').focus();};
  $('test-submit').onclick=()=>{const result=engine.submitTest();confirmSubmit=false;onProgress();location.hash='selftest/'+result.id;selftest(result.id);focusTest();};
  $('test-discard').onclick=()=>{if(!window.confirm('Discard this unfinished self-test?'))return;engine.discardTest();confirmSubmit=false;location.hash='selftest';selftest();};
 }
 function result(t){const breakdown=[...new Set(t.items.map(q=>q.chapter))].sort((a,b)=>a-b).map(c=>({chapter:c,total:t.items.filter(q=>q.chapter===c).length,score:t.grades.filter(g=>g.correct&&t.items.find(q=>q.id===g.id).chapter===c).length}));
  $('learning-selftest').innerHTML='<h3 id="test-result-title" tabindex="-1">Self-test result: '+t.score+' / '+t.items.length+'</h3><p>'+html(new Date(t.submittedAt).toLocaleString('en-GB'))+' · '+Math.round(t.score/t.items.length*100)+'% correct</p><ul class="test-breakdown">'+breakdown.map(c=>'<li>Chapter '+c.chapter+': '+c.score+' / '+c.total+'</li>').join('')+'</ul><div class="learning-actions"><a href="#selftest" class="main-btn">Set up another test</a>'+(breakdown.some(c=>c.score<c.total)?'<button type="button" id="test-weak">Test weaker chapters again</button>':'')+'</div><div class="test-results">'+t.items.map((q,i)=>{const g=t.grades[i],live=byId.get(q.id);return '<article class="test-result '+(g.correct?'correct':'')+'"><h4>'+ (i+1)+'. '+html(q.prompt)+'</h4><p><strong>'+ (g.correct?'Correct':g.unanswered?'Unanswered':g.valid?'Incorrect':'Invalid answer')+'</strong> · Chapter '+q.chapter+' · '+html(q.level)+'</p><p>Your answer: '+html(g.raw||'—')+' '+html(q.unit)+'<br>Expected: '+html(number(q.expected))+' '+html(q.unit)+'</p><details><summary>Worked solution</summary><ol>'+q.steps.map(s=>'<li>'+html(s)+'</li>').join('')+'</ol></details>'+(live?'<a href="#exercise/'+encodeURIComponent(q.id)+'">Practise this question →</a>'+resources(live):'')+'</article>';}).join('')+'</div>'+historyMarkup();
  if($('test-weak'))$('test-weak').onclick=()=>{if(engine.activeTest){location.hash='selftest/'+engine.activeTest.id;selftest(engine.activeTest.id);return;}history.replaceState(null,'','#selftest');setup();const weak=breakdown.filter(c=>c.score<c.total).map(c=>String(c.chapter));document.querySelectorAll('[name="test-chapter"]').forEach(n=>n.checked=weak.includes(n.value));$('test-setup').dispatchEvent(new Event('change',{bubbles:true}));$('test-setup').scrollIntoView?.({block:'start'});};
 }
 function selftest(id){resultId=id||null;const submitted=id&&engine.history.find(t=>t.id===id);if(submitted)result(submitted);else if(engine.activeTest)active(engine.activeTest);else setup();storage();}
 return {progress,selftest,practice,checked,reset,resources,tabChanged(name,id){if(name==='progress')progress();if(name==='selftest')selftest(id);},emptyPractice(){current=null;$('exercise-resources').innerHTML='';$('next-solution-step').disabled=true;$('exercise-steps').hidden=true;}};
}
root.MT_LEARNING_WORKSPACE={create};
})(typeof window!=='undefined'?window:globalThis);
